// Fail loudly rather than POSTing to "undefined/api/drain".
// A drain that silently stops is the failure mode this whole system is
// built to avoid: the outbox keeps filling, nothing errors, and the first
// symptom is a lead that never reached Airtable.
const row = $input.first()?.json ?? {};

const baseUrl = String(row.public_base_url ?? '').trim().replace(/\/+$/, '');
const drainSecret = String(row.drain_secret ?? '').trim();

if (!baseUrl || !drainSecret) {
  throw new Error(
    'app_config is missing public_base_url or drain_secret. ' +
      'Insert the row in Supabase (see supabase/schema.sql) before this workflow can run.'
  );
}

return [{ json: { baseUrl, drainSecret } }];
